/**
 * The boot screen: your mark in the start-up animation, static or flashing, and
 * the tunnel's density.
 *
 * The browser half of `src/dnfw/mods/bootscreen.py`, which carries the evidence.
 * Same names, same order, so drift between the two is visible -- and
 * `scripts/js_bootscreen_check.mjs` fails if the bytes they produce differ.
 *
 * The code is fixed and pre-assembled (`bootscreen-code.js`, generated by
 * `scripts/gen_bootscreen_code.py`); everything a user chooses is data:
 *
 * - one or two whole 128 x 64 images -- one is held, two alternate;
 * - the flashing: every 2^slow frames, every 2^fast from frame `rush`, image 0
 *   held from frame `stop`;
 * - the tunnel's texture scale, stock 128 x 64.
 *
 * All of it lands in a `BOOT` (or `ANIM`) chunk of the platform's area past the
 * end of MAIN OS, and the stamp that shows it in a CODE chunk at 0x46708000; the
 * platform loader copies both up before the BSS clear (`platform.js`). The mark
 * was proven on the instrument on 2026-09-17 by `intro-bang`, with the stamp in
 * a cave and a copy stub of its own; the stamp's bytes are unchanged.
 */

import { CODE } from "./bootscreen-code.js";
import * as platform from "./platform.js";
import { W as GW, frames as glitchFrames, GlitchError } from "../asciiglitch.js";
import { frames as spinGrids, SpinError } from "../batspin.js";

export const ID = "bootscreen";
export const NAME = "Boot screen";
export const SECTION = 3;
export const W = 128;
export const H = 64;
export const IMAGE_BYTES = 1024;
export const STOCK_TUNNEL = [128.0, 64.0];
const BASE = 0x40000400;

export class ModError extends Error {}

const hex = (s) => Uint8Array.from(s.match(/../g).map((b) => parseInt(b, 16)));
const toHex = (a) => Array.from(a, (b) => b.toString(16).padStart(2, "0")).join("");
const be32 = (v) => new Uint8Array([(v >>> 24) & 255, (v >>> 16) & 255, (v >>> 8) & 255, v & 255]);
const f32 = (v) => { const b = new Uint8Array(4); new DataView(b.buffer).setFloat32(0, v, false); return b; };
const cat = (...parts) => {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of parts) { out.set(p, at); at += p.length; }
  return out;
};

/**
 * Lit pixels -> the 1,024 bytes the intro's source bitmap holds. Column-major,
 * two longwords per column: pixel (x, y) is bit `31 - (y & 31)` of longword
 * `x * 2 + (y >> 5)` -- the layout the firmware's own `setPixel` writes.
 * `lit(x, y)` returns whether a pixel is on.
 */
export function imageFromPixels(lit) {
  const words = new Uint32Array(CODE.words);
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      if (lit(x, y)) words[x * 2 + (y >> 5)] |= (0x80000000 >>> (y & 31));
    }
  }
  const out = new Uint8Array(IMAGE_BYTES);
  const view = new DataView(out.buffer);
  words.forEach((w, i) => view.setUint32(i * 4, w >>> 0, false));
  return out;
}

/** The inverse image, for the flashing build-up. */
export const invert = (image) => image.map((b) => (~b) & 0xff);

/** Whether pixel (x, y) is lit in a 1,024-byte image -- for previews. */
export function pixelOf(image, x, y) {
  const at = (x * 2 + (y >> 5)) * 4;
  const w = ((image[at] << 24) >>> 0) + (image[at + 1] << 16) + (image[at + 2] << 8) + image[at + 3];
  return ((w >>> (31 - (y & 31))) & 1) === 1;
}

export function bootChunk(images, { slow, fast, rush, stop }) {
  if (!(images.length >= 1 && images.length <= 2)) {
    throw new ModError("a boot screen has one image (static) or two (flashing)");
  }
  for (const img of images) {
    if (img.length !== IMAGE_BYTES) throw new ModError(`an image is ${img.length} bytes, not ${IMAGE_BYTES}`);
  }
  for (const [name, v] of [["slow", slow], ["fast", fast]]) {
    if (!(Number.isInteger(v) && v >= 0 && v <= 16)) throw new ModError(`${name} must be a shift of 0..16 frames`);
  }
  if (!(rush >= 0 && rush <= stop)) throw new ModError(`rush (${rush}) must not come after stop (${stop})`);
  return cat(be32(images.length), be32(slow), be32(fast), be32(rush), be32(stop), ...images);
}

/**
 * The ANIM chunk -- any animation drawn ahead of time: u32 frames, u32 loop start, then each frame as a whole
 * 1,024-byte source bitmap. Past the last frame the intro loops from `loopStart`.
 */
export function animChunk(frames, loopStart) {
  if (!frames.length) throw new ModError("an ASCII animation needs at least one frame");
  for (const img of frames) {
    if (img.length !== IMAGE_BYTES) throw new ModError(`a frame is ${img.length} bytes, not ${IMAGE_BYTES}`);
  }
  if (!(loopStart >= 0 && loopStart < frames.length)) {
    throw new ModError(`loop start ${loopStart} is not a frame of ${frames.length}`);
  }
  return cat(be32(frames.length), be32(loopStart), ...frames);
}

/**
 * The mark as a glitching ASCII animation -> [frames as images, loop start].
 * Frames are stored upside down: the plain blit that shows them turns the
 * source over (see `bootscreen.py`'s `_images`).
 */
export function asciiFrames(lit, options = {}) {
  let grids;
  try { grids = glitchFrames(lit, options); } catch (e) {
    if (e instanceof GlitchError) throw new ModError(e.message);
    throw e;
  }
  const images = grids.map((g) => imageFromPixels((x, y) => g[(H - 1 - y) * GW + x] === 1));
  return [images, Math.min(options.resolve ?? 40, images.length - 1)];
}

/** The mark as a 1966-style spinning transition -> [frames as images, loop start]. */
export function spinFrames(lit, options = {}) {
  let grids;
  try { grids = spinGrids(lit, options); } catch (e) {
    if (e instanceof SpinError) throw new ModError(e.message);
    throw e;
  }
  return [grids.map((g) => imageFromPixels((x, y) => g[(H - 1 - y) * GW + x] === 1)), options.resolve ?? 120];
}

/** The shared appended area: 'DNFW', total length, a directory, the chunks. */
export function extents(areaLength = 0) {
  const off = (va) => va - BASE;
  return [
    { section: SECTION, start: off(CODE.intro_va), length: 8, what: "intro hook: the mark" },
    { section: SECTION, start: off(CODE.tunnel_x_va) + 2, length: 4, what: "tunnel scale x" },
    { section: SECTION, start: off(CODE.tunnel_y_va) + 2, length: 4, what: "tunnel scale y" },
    ...platform.extents(areaLength),
  ];
}

/**
 * -> `{ content, notes, extents }`. `content` is the whole new MAIN OS, with the
 * mark's chunks and the stamp's CODE chunk added to the platform's area.
 * Refuses anything that is not stock Digitone II 1.11 at every site it writes.
 */
export function apply(firmware, images, {
  slow = 4, fast = 3, rush = 48, stop = 72, tunnel = STOCK_TUNNEL, ascii = null,
} = {}) {
  const section = firmware.container.find(SECTION);
  if (section === null) throw new ModError("image has no MAIN OS section");
  const original = section.unpack();
  if (original === null) throw new ModError("MAIN OS did not depack");
  const [base, others] = platform.split(original);

  const have = toHex(base.subarray(CODE.intro_va - BASE, CODE.intro_va - BASE + 8));
  if (have !== CODE.intro_stock) {
    throw new ModError(`0x${CODE.intro_va.toString(16).padStart(8, "0")} holds ${have}, not `
      + `${CODE.intro_stock} (intro copy routine); this mod is for Digitone II 1.11, or the `
      + "boot screen is already applied");
  }
  for (const [va, stock] of [[CODE.tunnel_x_va, STOCK_TUNNEL[0]], [CODE.tunnel_y_va, STOCK_TUNNEL[1]]]) {
    if (toHex(base.subarray(va - BASE + 2, va - BASE + 6)) !== toHex(f32(stock))) {
      throw new ModError("the tunnel scale is not stock");
    }
  }

  const chunks = [];
  if (ascii) chunks.push([CODE.anim_chunk, animChunk(...ascii)]);
  if (images && images.length) chunks.push([CODE.boot_chunk, bootChunk(images, { slow, fast, rush, stop })]);
  if (!chunks.length) throw new ModError("give a mark (images) or an ASCII animation");
  chunks.push([platform.CODE, platform.codeChunk(CODE.load, hex(CODE.code))]);

  const edited = base.slice();
  edited.set(cat(new Uint8Array([0x4e, 0xf9]), be32(CODE.stamp), new Uint8Array([0x4e, 0x71])), CODE.intro_va - BASE);
  for (const [va, scale] of [[CODE.tunnel_x_va, tunnel[0]], [CODE.tunnel_y_va, tunnel[1]]]) {
    if (!(scale >= 1 && scale <= 65536)) throw new ModError(`tunnel scale ${scale} is outside 1..65536`);
    edited.set(f32(scale), va - BASE + 2);
  }
  const content = platform.join(edited, [...others, ...chunks]);
  const areaBytes = content.length - platform.STOCK_LENGTH;

  const notes = [
    ascii ? `animation: ${ascii[0].length} frames, looping from ${ascii[1]}`
      : `${images.length} image(s), ` + (images.length === 1 ? "static"
      : `flashing every 2^${slow} then 2^${fast} frames from ${rush}, held from ${stop}`),
    `the platform's area ${areaBytes.toLocaleString()} B; MAIN OS ${content.length.toLocaleString()} B`,
  ];
  return { content, notes, extents: extents(areaBytes) };
}
